import{_ as s,o as t,c as a,Q as o}from"./chunks/framework.b67c47e6.js";const E=JSON.parse('{"title":"API v2","description":"","frontmatter":{},"headers":[],"relativePath":"guide/api/index.md","filePath":"guide/api/index.md","lastUpdated":1786606471000}'),e={name:"guide/api/index.md"},n=o(`<h1 id="api-v2" tabindex="-1">API v2 <a class="header-anchor" href="#api-v2" aria-label="Permalink to &quot;API v2&quot;">​</a></h1><p>The produuz.it REST API lets you automate design uploads, constructible management, report generation, and more from external systems.</p><nav class="table-of-contents"><ul><li><a href="#interactive-documentation">Interactive Documentation</a></li><li><a href="#authentication">Authentication</a></li><li><a href="#main-endpoint-groups">Main Endpoint Groups</a></li><li><a href="#common-workflows">Common Workflows</a></li><li><a href="#material-quantities-for-purchasing">Material Quantities for Purchasing</a></li><li><a href="#rate-limits">Rate Limits</a></li></ul></nav><h2 id="interactive-documentation" tabindex="-1">Interactive Documentation <a class="header-anchor" href="#interactive-documentation" aria-label="Permalink to &quot;Interactive Documentation&quot;">​</a></h2><p>The full API is documented through an interactive Swagger interface:</p><ul><li><strong>Swagger UI:</strong> <a href="https://back.produuz.it/api/v2/auth/login/?next=/api/v2/swagger/" target="_blank" rel="noreferrer">back.produuz.it/api/v2/swagger/</a></li><li><strong>OpenAPI Schema:</strong> Available at the same URL for importing into API clients.</li></ul><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The API uses <strong>JWT (JSON Web Token)</strong> authentication with OTP (one-time password) verification.</p><ol><li><strong>Obtain a token</strong> — <code>POST /api/v2/my_user/token/</code> with your credentials and OTP code.</li><li><strong>Include the token</strong> — Add <code>Authorization: Bearer &lt;token&gt;</code> to all subsequent requests.</li><li><strong>Refresh the token</strong> — <code>POST /api/v2/my_user/token/refresh/</code> before the token expires.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For automated integrations, ask your admin to create an <strong>API Account</strong> in Company Settings. API accounts can authenticate without OTP.</p></div><h2 id="main-endpoint-groups" tabindex="-1">Main Endpoint Groups <a class="header-anchor" href="#main-endpoint-groups" aria-label="Permalink to &quot;Main Endpoint Groups&quot;">​</a></h2><table><thead><tr><th>Group</th><th>Base path</th><th>Description</th></tr></thead><tbody><tr><td><strong>Constructibles</strong></td><td><code>/api/v2/constructibles/</code></td><td>Designs, actuals (assemblies/modules), batches, parts</td></tr><tr><td><strong>Company</strong></td><td><code>/api/v2/company/</code></td><td>Projects, users, IFC parsing setups, API accounts</td></tr><tr><td><strong>Reports</strong></td><td><code>/api/v2/reports/</code></td><td>Report creation and status tracking</td></tr><tr><td><strong>Factories</strong></td><td><code>/api/v2/factories/</code></td><td>Production lines, stations, machines, triggers</td></tr><tr><td><strong>Cloud Storage</strong></td><td><code>/api/v2/cloudstorage/</code></td><td>File uploads and package management</td></tr><tr><td><strong>Logistics</strong></td><td><code>/api/v2/logistics/</code></td><td>Materials, stock, sizes, orders, delivery</td></tr><tr><td><strong>Records</strong></td><td><code>/api/v2/records/</code></td><td>Issues, production events</td></tr><tr><td><strong>Integrations</strong></td><td><code>/api/v2/integrations/</code></td><td>Webhooks</td></tr><tr><td><strong>User</strong></td><td><code>/api/v2/my_user/</code></td><td>Profile, authentication, settings</td></tr></tbody></table><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><p>For step-by-step API tutorials, see <a href="/tutorials/api/">Connecting to the API</a>:</p><ul><li><a href="/tutorials/api/post_designs/">Upload and create designs</a></li><li><a href="/tutorials/api/designs/">Fetch and filter designs</a></li><li><a href="/tutorials/api/constructibles/">Generate constructibles</a></li><li><a href="/tutorials/api/reports/">Generate reports and machine files</a></li></ul><h2 id="material-quantities-for-purchasing" tabindex="-1">Material Quantities for Purchasing <a class="header-anchor" href="#material-quantities-for-purchasing" aria-label="Permalink to &quot;Material Quantities for Purchasing&quot;">​</a></h2><p>To order material you don&#39;t need to download every part. Ask the sizes endpoint for the material in scope and let it count for you:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">POST /api/v2/logistics/sizes/profiles/names_and_actual_dims/</span></span>
<span class="line"><span style="color:#e1e4e8;">POST /api/v2/logistics/sizes/plates/names_and_actual_dims/</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">POST /api/v2/logistics/sizes/profiles/names_and_actual_dims/</span></span>
<span class="line"><span style="color:#24292e;">POST /api/v2/logistics/sizes/plates/names_and_actual_dims/</span></span></code></pre></div><p>The scope goes in the body as uuid lists, which are OR-ed together. Any of <code>projects</code>, <code>assemblies</code>, <code>part_batches</code> and <code>modules</code> works. Add <code>with_counts</code> to get the quantities:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">{ </span><span style="color:#79B8FF;">&quot;projects&quot;</span><span style="color:#E1E4E8;">: [</span><span style="color:#9ECBFF;">&quot;&lt;project uuid&gt;&quot;</span><span style="color:#E1E4E8;">], </span><span style="color:#79B8FF;">&quot;with_counts&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">true</span><span style="color:#E1E4E8;"> }</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">{ </span><span style="color:#005CC5;">&quot;projects&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;&lt;project uuid&gt;&quot;</span><span style="color:#24292E;">], </span><span style="color:#005CC5;">&quot;with_counts&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">true</span><span style="color:#24292E;"> }</span></span></code></pre></div><p>Each entry is one material size with its cut dimensions. For profiles the dimension is the cut length in mm; for plates it is <code>length*width</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">[{</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;size&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;VUREN_C24 38*120&quot;</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;actual_dims&quot;</span><span style="color:#E1E4E8;">: [</span><span style="color:#9ECBFF;">&quot;5630&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#9ECBFF;">&quot;5380&quot;</span><span style="color:#E1E4E8;">],</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;dims&quot;</span><span style="color:#E1E4E8;">: [</span></span>
<span class="line"><span style="color:#E1E4E8;">    {</span><span style="color:#79B8FF;">&quot;dim&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;5630&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;count&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">2</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;total_length&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">11260.0</span><span style="color:#E1E4E8;">},</span></span>
<span class="line"><span style="color:#E1E4E8;">    {</span><span style="color:#79B8FF;">&quot;dim&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#9ECBFF;">&quot;5380&quot;</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;count&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">4</span><span style="color:#E1E4E8;">, </span><span style="color:#79B8FF;">&quot;total_length&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">21520.0</span><span style="color:#E1E4E8;">}</span></span>
<span class="line"><span style="color:#E1E4E8;">  ],</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;count&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">148</span><span style="color:#E1E4E8;">,</span></span>
<span class="line"><span style="color:#E1E4E8;">  </span><span style="color:#79B8FF;">&quot;total_length&quot;</span><span style="color:#E1E4E8;">: </span><span style="color:#79B8FF;">115766.0</span></span>
<span class="line"><span style="color:#E1E4E8;">}]</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">[{</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;size&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;VUREN_C24 38*120&quot;</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;actual_dims&quot;</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&quot;5630&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;5380&quot;</span><span style="color:#24292E;">],</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;dims&quot;</span><span style="color:#24292E;">: [</span></span>
<span class="line"><span style="color:#24292E;">    {</span><span style="color:#005CC5;">&quot;dim&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;5630&quot;</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;count&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;total_length&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">11260.0</span><span style="color:#24292E;">},</span></span>
<span class="line"><span style="color:#24292E;">    {</span><span style="color:#005CC5;">&quot;dim&quot;</span><span style="color:#24292E;">: </span><span style="color:#032F62;">&quot;5380&quot;</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;count&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">4</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">&quot;total_length&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">21520.0</span><span style="color:#24292E;">}</span></span>
<span class="line"><span style="color:#24292E;">  ],</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;count&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">148</span><span style="color:#24292E;">,</span></span>
<span class="line"><span style="color:#24292E;">  </span><span style="color:#005CC5;">&quot;total_length&quot;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">115766.0</span></span>
<span class="line"><span style="color:#24292E;">}]</span></span></code></pre></div><ul><li><code>count</code> is the number of parts to cut. Deprecated parts — replaced or deleted work — are not counted, so the quantities are orderable as they come.</li><li>Totals come as <code>total_length</code> in mm for profiles and <code>total_area</code> in mm2 for plates.</li><li>Without <code>with_counts</code> you get only <code>size</code> and <code>actual_dims</code>, which is the cheaper call for filling in a material selector.</li><li><code>with_counts</code> needs a scope: counting a whole company catalogue is rejected with a <code>400</code>.</li><li>Scope by <code>projects</code>, <code>assemblies</code> or <code>part_batches</code>. A part inside a panel that sits inside a module is only linked to the panel, so scoping by <code>modules</code> alone can miss parts.</li></ul><h2 id="rate-limits" tabindex="-1">Rate Limits <a class="header-anchor" href="#rate-limits" aria-label="Permalink to &quot;Rate Limits&quot;">​</a></h2><p>The API enforces rate limits to ensure fair usage. If you receive a <code>429 Too Many Requests</code> response, wait before retrying.</p>`,25),l=[n];function p(r,i,c,d,u,h){return t(),a("div",null,l)}const g=s(e,[["render",p]]);export{E as __pageData,g as default};
